#include "../../models/film_routed_tendon/Step.h"
#include <iomanip>
#include <iostream>
using namespace regrip_routed_tendon;
int main(int argc,char**argv){try{
 if(argc!=5)throw std::runtime_error("mass,samples,amplitude,output required");auto m=model();auto mass=publicMass(argv[1]);double amplitude=std::stod(argv[3]);validate(m,amplitude);std::ifstream in(argv[2]);unsigned n;in>>n;if(!in||n<2||n>4000||n%2)throw std::runtime_error("bounded complete actual Gauss pairs required");std::ofstream out(argv[4]);out<<std::setprecision(17)<<"time,weight,T,tendon_power_Nmm_s,damping_power_Nmm_s,tendon_work_Nmm,damping_work_Nmm,attachment_skin_force_norm_N,attachment_rail_force_norm_N,tendon_force_norm_N,cable_length_mm,skin75_attachment_Fz_N,rail75_attachment_Fz_N,rail75_tendon_Fz_N\n";double W=0,D=0;
 for(unsigned k=0;k<n;++k){double t,w,T;in>>t>>w>>T;std::vector<Point>q(m.size()),v(m.size()),bond(m.size()),cable(m.size());for(auto&x:q)for(double&y:x)in>>y;for(auto&x:v)for(double&y:x)in>>y;if(!in||w<=0||T<0)throw std::runtime_error("invalid actual stage payload");elements(m,q,1,amplitude,[&](const Element&e){if(e.kind==1||e.kind==2)for(unsigned a=0;a<3*e.ids.size();++a)(e.kind==1?bond:cable)[e.ids[a/3]][a%3]-=e.energy.g[a];});double K=0,power=0,bs=0,br=0,ct=0;for(unsigned i=0;i<q.size();++i){K+=.5*mass[i]*dot(v[i],v[i]);power+=T*dot(cable[i],v[i]);(i<105?bs:br)+=dot(bond[i],bond[i]);ct+=dot(cable[i],cable[i]);}double skin75=0,rail75=0,cable75=0;for(unsigned part=0;part<3;++part)for(unsigned j=0;j<m.parts[part].ny;++j){unsigned id=m.id(part,15,j);if(part==0)skin75+=bond[id][2];else{rail75+=bond[id][2];cable75+=T*cable[id][2];}}double damping=4*K;W+=w*power;D+=w*damping;out<<t<<','<<w<<','<<T<<','<<power<<','<<damping<<','<<W<<','<<D<<','<<std::sqrt(bs)<<','<<std::sqrt(br)<<','<<T*std::sqrt(ct)<<','<<length(m,q,amplitude)<<','<<skin75<<','<<rail75<<','<<cable75<<'\n';out.flush();}
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
